class Solution {
    public void moveZeroes(int[] nums) {
        int j = 0;                                  // 下一个非零数放的位置
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] != 0) {
                int t = nums[i];
                nums[i] = nums[j];
                nums[j] = t;
                j++;
            }
        }
    }
}

