class Solution {
public:
    void moveZeroes(vector<int>& nums) {
        int j = 0;                                  // 下一个非零数放的位置
        for (int i = 0; i < nums.size(); i++) {
            if (nums[i] != 0) {
                swap(nums[i], nums[j]);
                j++;
            }
        }
    }
};

